availableTools.inputSchemaJson:
{
  "type":"object",
  "properties":{
    "purpose":{"type":"string","maxLength":500,"description":"说明要读取什么以及用途。"},
    "toolCallId":{"type":"string","format":"uuid","description":"要读取的原工具调用标识。"},
    "expression":{"type":"string","minLength":1,"maxLength":2000,"description":"只读 JavaScript 表达式；完整原始 JSON 绑定为 result。例如 result.data.items[0]、result.nodes.length 或 ({total:result.nodes.length,values:result.nodes.slice(0,50)})。"}
  },
  "required":["purpose","toolCallId","expression"],
  "additionalProperties":false,
  "x-agentcore-require-purpose":false
}
